// ─── Module 0: Numbers & Finance ────────────────────────────────────────────
LESSON_DB.math_lit.m0 = {
  0: {emoji:"🏷️", subtitle:"Grade 10 · Discounts, increases and sharing fairly",
    illusText:"“25% off!” “Mix 1 : 4!” “5% increase!” — percentages and ratios are on every shelf, bottle and payslip.",
    hook:{title:"Is the Black Friday deal real?", body:"A TV is advertised at R1 200 with “25% off”. That's a saving of R300, so you pay <strong>R900</strong>. But if the shop raised the price from R1 000 the week before, the real discount is only 10%. Percentages let you check whether a deal is actually a deal."},
    intro:"A <strong>percentage</strong> means “out of 100”: 25% = 25/100 = 0.25. To find a percentage of an amount, multiply: 25% of R1 200 = 0.25 × 1 200 = R300. <strong>Percentage change</strong> = (new − old) ÷ old × 100. A <strong>ratio</strong> compares quantities in the same units, e.g. concentrate : water = 1 : 4, meaning 1 part concentrate for every 4 parts water (5 parts in total).",
    concepts:[
      {t:"green", title:"➖ Discount and increase", body:"Discount: price × (1 − %). Increase: amount × (1 + %). A 5% increase on R8 000 = 8 000 × 1.05 = R8 400."},
      {t:"teal", title:"🥤 Sharing in a ratio", body:"Add the parts, find one part, then multiply. 2 L of juice in 1 : 4 → 5 parts → 1 part = 400 ml concentrate, 1 600 ml water."},
      {t:"gold", title:"🍲 Scaling recipes", body:"A recipe for 4 people needs 500 g samp. For 10 people: 10 ÷ 4 = 2.5 → 2.5 × 500 g = 1.25 kg."},
    ],
    examples:[
      {title:"The TV discount", body:"R1 200 with 25% off.", answer:"0.25 × 1 200 = R300 off → <strong>R900</strong>."},
      {title:"Salary increase", body:"R8 000 rises to R8 400. Percentage increase?", answer:"(8 400 − 8 000)/8 000 × 100 = <strong>5%</strong>."},
      {title:"Juice ratio", body:"Make 2 L of juice with concentrate : water = 1 : 4.", answer:"1 part = 2 000 ÷ 5 = <strong>400 ml concentrate</strong>, 1 600 ml water."},
    ],
    formula:"% change = (new − old)/old × 100 · one part = total ÷ number of parts",
    mistakes:["Dividing by the new value instead of the old value for % change.","Thinking a 10% increase followed by a 10% decrease gets you back where you started (it doesn't).","Mixing units in a ratio (e.g. ml and L)."],
    callout:{title:"Where you'll use this", body:"Shopping and sales, salary negotiations, mixing paint, cement or fertiliser, cooking for a crowd and reading interest rates."},
    activity:"Concrete is mixed cement : sand : stone = 1 : 2 : 3. How many wheelbarrows of each for 30 wheelbarrows of concrete?",
    activityAnswer:"6 parts → 1 part = 5 barrows. Cement 5, sand 10, stone 15.",
    examTip:"Show the formula, the substitution and the answer with units (R, %, ml). Maths Lit marks the method, not just the answer.",
    keyterms:[{w:"Percentage",d:"A number out of 100"},{w:"Ratio",d:"Comparison of quantities in the same units"},{w:"Percentage change",d:"Change compared with the original value, × 100"}],
    quiz:[
      {q:"15% of R400 is:",opts:["R15","R40","R60","R85"],a:2,et:"0.15 × 400 = R60."},
      {q:"R50 increases to R60. The % increase is:",opts:["10%","16.7%","20%","60%"],a:2,et:"(60 − 50)/50 × 100 = 20%."},
      {q:"Share R300 in the ratio 1 : 2. The larger share is:",opts:["R100","R150","R200","R250"],a:2,et:"3 parts → R100 each → 2 parts = R200."},
    ],
    conclusion:"Percentages and ratios are the language of prices and recipes. Check every deal with a quick calculation."},

  1: {emoji:"🐷", subtitle:"Grade 10–12 · Growing money — or growing debt",
    illusText:"A stokvel that invests its savings earns interest on interest. A store card does the same thing — against you.",
    hook:{title:"The stokvel's savings", body:"A stokvel puts R12 000 into a fixed deposit at 7% per year, compounded annually. After 3 years it's worth <strong>R14 700.52</strong>. With simple interest it would be R14 520 — the extra R180.52 is interest earning interest. The longer the money stays, the bigger that gap becomes."},
    intro:"<strong>Simple interest</strong> is calculated on the original amount only: A = P(1 + i × n). <strong>Compound interest</strong> is calculated on the amount including earlier interest: A = P(1 + i)ⁿ. P is the amount invested or borrowed, i the interest rate as a decimal and n the number of periods. In Maths Lit you can also calculate compound interest year by year in a table.",
    concepts:[
      {t:"green", title:"📋 Year-by-year table", body:"Year 1: 12 000 × 1.07 = 12 840. Year 2: 12 840 × 1.07 = 13 738.80. Year 3: 13 738.80 × 1.07 = 14 700.52."},
      {t:"teal", title:"🏦 Savings vs debt", body:"Compound interest helps savings grow and makes unpaid debt grow quickly. Paying off a credit card in full each month avoids interest."},
      {t:"gold", title:"📊 Comparing offers", body:"Higher rate and more frequent compounding give more growth. Always compare the total amount, not just the instalment."},
    ],
    examples:[
      {title:"Compound", body:"R12 000 at 7% p.a. compounded annually for 3 years.", answer:"12 000 × 1.07³ = <strong>R14 700.52</strong>."},
      {title:"Simple", body:"Same amount, 7% simple interest, 3 years.", answer:"12 000 × (1 + 0.07 × 3) = <strong>R14 520</strong>."},
      {title:"Interest earned", body:"How much interest did the compound investment earn?", answer:"14 700.52 − 12 000 = <strong>R2 700.52</strong>."},
    ],
    formula:"Simple: A = P(1 + i × n) · Compound: A = P(1 + i)ⁿ",
    mistakes:["Using 7 instead of 0.07.","Adding the interest only once in compound interest.","Confusing the final amount with the interest earned."],
    callout:{title:"Where you'll use this", body:"Stokvels, savings accounts, tax-free savings, retirement funds, and understanding why debt is expensive."},
    activity:"R5 000 is saved at 6% compound interest per year. Complete a table for 4 years.",
    activityAnswer:"Y1 R5 300; Y2 R5 618; Y3 R5 955.08; Y4 R6 312.38.",
    examTip:"If a question says “show your working in a table”, do so — a correct final answer without the table can lose marks.",
    keyterms:[{w:"Principal",d:"The original amount invested or borrowed"},{w:"Simple interest",d:"Interest on the principal only"},{w:"Compound interest",d:"Interest on principal plus earlier interest"}],
    quiz:[
      {q:"R1 000 at 10% simple interest for 2 years becomes:",opts:["R1 100","R1 200","R1 210","R2 000"],a:1,et:"1 000 × (1 + 0.1 × 2) = R1 200."},
      {q:"R1 000 at 10% compound interest for 2 years becomes:",opts:["R1 200","R1 210","R1 100","R1 220"],a:1,et:"1 000 × 1.1² = R1 210."},
      {q:"Compound interest is better for:",opts:["Borrowers","Savers","Nobody","Shops"],a:1,et:"Your savings earn interest on interest."},
    ],
    conclusion:"Simple interest grows in a straight line; compound interest grows faster every year. Use it to save — and avoid it in debt."},

  2: {emoji:"📺", subtitle:"Grade 11–12 · The true cost of buying on credit",
    illusText:"“Only R320 a month!” sounds cheap — until you add up all 24 months.",
    hook:{title:"“Only R320 a month”", body:"A TV costs R6 000 cash. On hire purchase it's a 10% deposit (R600) plus <strong>24 payments of R320</strong>. That's R8 280 in total — <strong>R2 280 more</strong> than paying cash. Before signing any credit agreement, multiply the instalment by the number of months and add the deposit."},
    intro:"<strong>Hire purchase (HP)</strong> lets you take goods home and pay in instalments, usually with a deposit and interest. A <strong>loan</strong> gives you money to repay with interest. The <strong>total cost of credit</strong> = deposit + (instalment × number of instalments). The <strong>cost of credit</strong> = total cost − cash price. The National Credit Act protects consumers: lenders must disclose the total cost and check you can afford it.",
    concepts:[
      {t:"green", title:"🧮 Total cost", body:"Deposit + instalments + any fees (initiation, monthly service fees, insurance). The fees can add a lot."},
      {t:"teal", title:"⚠️ Mashonisas", body:"Informal lenders often charge very high interest (e.g. 30% per month) and may illegally keep ID books or SASSA cards. That's against the law."},
      {t:"gold", title:"✅ Smart borrowing", body:"Compare total cost, not monthly instalment. Pay a bigger deposit or shorter term if possible. Save first for non-essential items."},
    ],
    examples:[
      {title:"The TV on HP", body:"Deposit 10% of R6 000, then 24 × R320.", answer:"R600 + R7 680 = <strong>R8 280</strong>. Cost of credit = <strong>R2 280</strong>."},
      {title:"Cash vs credit percentage", body:"How much more is the HP price than cash, as a %?", answer:"2 280 ÷ 6 000 × 100 = <strong>38%</strong> more."},
      {title:"Monthly fee", body:"A loan has a R69 monthly service fee for 24 months. Extra cost?", answer:"69 × 24 = <strong>R1 656</strong>."},
    ],
    formula:"Total cost = deposit + instalment × months · Cost of credit = total cost − cash price",
    mistakes:["Comparing only monthly instalments between offers.","Forgetting the deposit or monthly fees.","Thinking a longer term is cheaper because the instalment is smaller."],
    callout:{title:"Where you'll use this", body:"Buying furniture, phones and cars; student loans; avoiding debt traps; working in banking or retail credit."},
    activity:"A fridge costs R7 500 cash, or R750 deposit and 18 × R480. Calculate the cost of credit.",
    activityAnswer:"750 + 18 × 480 = 750 + 8 640 = R9 390. Cost of credit = 9 390 − 7 500 = R1 890.",
    examTip:"Maths Lit loves “Which option is better and why?” — calculate both totals and then give a reason using the numbers.",
    keyterms:[{w:"Hire purchase",d:"Buying goods on instalments, usually with a deposit"},{w:"Cost of credit",d:"Extra paid compared with the cash price"},{w:"National Credit Act",d:"Law protecting South African credit consumers"}],
    quiz:[
      {q:"Deposit R500 + 12 × R200. Total paid:",opts:["R2 400","R2 900","R2 500","R3 400"],a:1,et:"500 + 2 400 = R2 900."},
      {q:"The best way to compare credit offers:",opts:["Lowest instalment","Total cost","Shortest advert","Biggest shop"],a:1,et:"Compare the total amount you'll pay."},
      {q:"A lender keeping your SASSA card is:",opts:["Normal","Illegal","Required","A fee"],a:1,et:"It's against the law."},
    ],
    conclusion:"Credit has a price. Always calculate the total — then decide whether the item is worth it."},

  3: {emoji:"💱", subtitle:"Grade 10–12 · Converting between currencies",
    illusText:"Online shopping from overseas, a trip to Eswatini, petrol prices — all depend on the rand's exchange rate.",
    hook:{title:"How much is that laptop in rand?", body:"A laptop costs $500 on an overseas website. If the exchange rate is R18.50 to $1, that's <strong>R9 250</strong> — before shipping, import duty and VAT. When the rand weakens, imported goods (and petrol) become more expensive for every South African."},
    intro:"An <strong>exchange rate</strong> tells you how much of one currency equals one unit of another, e.g. $1 = R18.50 (rates change daily). To convert <strong>to rand</strong>, multiply by the rand amount per unit. To convert <strong>from rand</strong>, divide. Banks use a <strong>buying rate</strong> and a <strong>selling rate</strong> and may charge commission. Eswatini's lilangeni and Lesotho's loti are pegged 1 : 1 to the rand.",
    concepts:[
      {t:"green", title:"✖️ Foreign → rand", body:"$500 × R18.50 = R9 250."},
      {t:"teal", title:"➗ Rand → foreign", body:"R9 250 ÷ R18.50 = $500. Check: does the answer make sense? Dollars are worth more than rands, so you get fewer dollars."},
      {t:"gold", title:"📉 Strong vs weak rand", body:"Weak rand (more rands per dollar): imports and travel cost more; exports and tourism to SA benefit. Strong rand: the opposite."},
    ],
    examples:[
      {title:"Laptop", body:"$500 at R18.50/$.", answer:"500 × 18.50 = <strong>R9 250</strong>."},
      {title:"Spending money", body:"You change R3 700 into dollars at R18.50/$.", answer:"3 700 ÷ 18.50 = <strong>$200</strong>."},
      {title:"Eswatini trip", body:"A meal costs E120. In rand?", answer:"1 : 1 peg → <strong>R120</strong>."},
    ],
    formula:"Rand = foreign amount × rate · Foreign = rand ÷ rate",
    mistakes:["Multiplying when you should divide (check if the answer is sensible).","Ignoring commission or bank fees.","Using an old rate — rates change daily."],
    callout:{title:"Where you'll use this", body:"Online shopping, travel, import/export businesses, tourism and understanding petrol price changes."},
    activity:"A Mozambican tour costs 9 000 meticais. If R1 = 3.5 meticais, what does it cost in rand?",
    activityAnswer:"9 000 ÷ 3.5 ≈ R2 571.43.",
    examTip:"Write the rate as a sentence first (“R18.50 buys $1”) so you know whether to multiply or divide.",
    keyterms:[{w:"Exchange rate",d:"Value of one currency in terms of another"},{w:"Weak rand",d:"More rands needed to buy one unit of foreign currency"},{w:"Commission",d:"Fee charged for exchanging money"}],
    quiz:[
      {q:"$20 at R18/$ is:",opts:["R1.11","R38","R360","R180"],a:2,et:"20 × 18 = R360."},
      {q:"A weaker rand makes imported goods:",opts:["Cheaper","More expensive","Free","Unchanged"],a:1,et:"You need more rands to buy the same foreign price."},
      {q:"R100 in Eswatini emalangeni:",opts:["E10","E100","E1 000","E50"],a:1,et:"The lilangeni is pegged 1 : 1 to the rand."},
    ],
    conclusion:"Multiply to get rands, divide to get foreign currency — and always check the answer makes sense."},

  4: {emoji:"🧾", subtitle:"Grade 10–12 · Why prices rise and how VAT works",
    illusText:"Your till slip shows VAT. The news reports inflation. Both change what your money can buy.",
    hook:{title:"Reading the till slip", body:"South Africa's VAT is <strong>15%</strong>. A R200 item (excluding VAT) costs <strong>R230</strong> at the till. But brown bread, maize meal, milk, eggs, dried beans, rice and fresh fruit and vegetables are <strong>zero-rated</strong> — no VAT — to protect poorer households. Inflation then raises prices year after year, so R50 today buys less next year."},
    intro:"<strong>VAT (value-added tax)</strong> is added to most goods and services in SA at 15%. Price incl. VAT = price excl. VAT × 1.15. Price excl. VAT = price incl. VAT ÷ 1.15. <strong>Inflation</strong> is the general increase in prices over time, measured by Stats SA as the <strong>CPI</strong> (Consumer Price Index). If inflation is 5%, something costing R50 now will cost about R50 × 1.05 = R52.50 next year.",
    concepts:[
      {t:"green", title:"➕ Adding VAT", body:"R200 × 1.15 = R230. The VAT amount = R30."},
      {t:"teal", title:"➖ Removing VAT", body:"R115 ÷ 1.15 = R100. (Don't subtract 15% of R115 — that gives the wrong answer, R97.75.)"},
      {t:"gold", title:"📈 Inflation and salaries", body:"If your salary rises by less than inflation, you can afford less than before — your “real” income fell."},
    ],
    examples:[
      {title:"Add VAT", body:"Item costs R200 excl. VAT.", answer:"200 × 1.15 = <strong>R230</strong>."},
      {title:"Remove VAT", body:"Till price R115 incl. VAT. Price excl. VAT?", answer:"115 ÷ 1.15 = <strong>R100</strong>; VAT = R15."},
      {title:"Inflation", body:"A R50 item, 5% inflation, next year?", answer:"50 × 1.05 = <strong>R52.50</strong>."},
    ],
    formula:"incl. VAT = excl. × 1.15 · excl. VAT = incl. ÷ 1.15 · next year's price ≈ price × (1 + inflation)",
    mistakes:["Removing VAT by subtracting 15% of the inclusive price.","Thinking zero-rated means free (the item still has a price, just no VAT).","Confusing inflation with interest."],
    callout:{title:"Where you'll use this", body:"Running a small business (VAT registration at R1 million turnover), checking till slips, salary negotiations and budgeting."},
    activity:"A spaza owner buys stock for R1 380 including VAT. How much VAT did they pay?",
    activityAnswer:"Excl. VAT = 1 380 ÷ 1.15 = R1 200 → VAT = R180.",
    examTip:"When removing VAT, always divide by 1.15. Show the step so the examiner can see you didn't subtract 15%.",
    keyterms:[{w:"VAT",d:"Value-added tax, 15% in South Africa"},{w:"Zero-rated",d:"Goods with 0% VAT, e.g. maize meal and brown bread"},{w:"CPI",d:"Consumer Price Index — measures inflation"}],
    quiz:[
      {q:"R100 excl. VAT is how much incl. VAT?",opts:["R100","R115","R85","R150"],a:1,et:"100 × 1.15 = R115."},
      {q:"R230 incl. VAT excludes VAT as:",opts:["R195.50","R200","R215","R264.50"],a:1,et:"230 ÷ 1.15 = R200."},
      {q:"Which is zero-rated in SA?",opts:["Cooldrink","Maize meal","Chips","Airtime"],a:1,et:"Maize meal is a zero-rated basic food."},
    ],
    conclusion:"Multiply by 1.15 to add VAT, divide by 1.15 to remove it, and remember inflation quietly raises every price."},

  5: {emoji:"📒", subtitle:"Grade 10–12 · Planning where the money goes",
    illusText:"A budget isn't about having lots of money — it's about telling the money you have where to go.",
    hook:{title:"The household budget", body:"Thandeka and her brother share a flat in Pietermaritzburg on a combined income of R9 500 a month. Rent is R3 500, food R2 800, taxi fare to work R968 (R22 each way, 22 working days), electricity R600 and airtime/data R300. That leaves <strong>R1 332</strong>. Writing it down shows exactly what's left to save — or where to cut."},
    intro:"A <strong>budget</strong> is a plan for income and expenditure over a period (usually a month). <strong>Income</strong>: salary, grants, side business. <strong>Expenses</strong>: <strong>fixed</strong> (same each month — rent, school fees) and <strong>variable</strong> (change — food, electricity, transport). A <strong>surplus</strong> means income > expenses; a <strong>deficit</strong> means expenses > income. Businesses also use budgets to plan and to calculate <strong>break-even</strong> points.",
    concepts:[
      {t:"green", title:"📋 Making a budget", body:"List all income. List every expense (check bank statements and slips). Subtract. Plan savings first (“pay yourself first”)."},
      {t:"teal", title:"🚕 Hidden costs", body:"Small daily costs add up: R22 taxi × 2 trips × 22 days = R968 a month. A R15 cooldrink every school day ≈ R300 a month."},
      {t:"gold", title:"📊 Actual vs budget", body:"Compare what you planned with what you spent. The difference shows where to adjust next month."},
    ],
    examples:[
      {title:"Taxi fare", body:"R22 per trip, 2 trips a day, 22 days.", answer:"22 × 2 × 22 = <strong>R968</strong>."},
      {title:"What's left?", body:"Income R9 500; expenses R3 500 + R2 800 + R968 + R600 + R300.", answer:"Expenses = R8 168 → surplus = <strong>R1 332</strong>."},
      {title:"Savings goal", body:"They want R6 000 for an emergency fund. How long, saving the full surplus?", answer:"6 000 ÷ 1 332 ≈ 4.5 → <strong>5 months</strong>."},
    ],
    mistakes:["Forgetting irregular expenses (school uniforms, birthdays, funerals).","Only budgeting once and never checking actual spending.","Treating credit as extra income."],
    callout:{title:"Where you'll use this", body:"Running a household, managing a stokvel, starting a small business, and every job in finance or administration."},
    activity:"Draw up a monthly budget for a learner who gets R600 pocket money. Include transport, data, food and savings.",
    activityAnswer:"Example: transport R200, data R150, lunch R150, savings R100 = R600. Any plan where expenses ≤ income and savings are included is acceptable.",
    examTip:"Budget questions usually ask you to calculate a total, then comment. Always say whether there's a surplus or deficit and suggest one realistic change.",
    keyterms:[{w:"Budget",d:"Plan of expected income and expenses"},{w:"Surplus",d:"Income greater than expenses"},{w:"Fixed expense",d:"Cost that stays the same each month"}],
    quiz:[
      {q:"Rent is usually a:",opts:["Variable expense","Fixed expense","Income","Surplus"],a:1,et:"It's the same amount each month."},
      {q:"Income R5 000, expenses R5 400. This is a:",opts:["Surplus of R400","Deficit of R400","Break-even","Profit"],a:1,et:"Expenses exceed income by R400."},
      {q:"R10 a day for 30 days costs:",opts:["R30","R100","R300","R3 000"],a:2,et:"10 × 30 = R300."},
    ],
    conclusion:"A budget turns money stress into a plan. Track it, compare it, adjust it."},
};

// ─── Module 1: Measurement ──────────────────────────────────────────────────
LESSON_DB.math_lit.m1 = {
  0: {emoji:"🧱", subtitle:"Grade 10–12 · Fencing, tiling and painting",
    illusText:"Before you buy fencing, tiles or paint, measure. Perimeter and area save money and trips to the hardware store.",
    hook:{title:"Tiling the stoep", body:"Mr Ndlovu wants to tile a 12 m × 8 m stoep with 50 cm × 50 cm tiles. The area is 96 m², each tile covers 0.25 m², so he needs 384 tiles — plus about <strong>10% extra</strong> for cutting and breakages: <strong>423 tiles</strong>. Getting this right means one trip to the hardware store instead of three."},
    intro:"<strong>Perimeter</strong> is the distance around a shape (fencing, skirting, borders). <strong>Area</strong> is the space inside it, in square units (m², cm²). Rectangle: P = 2(l + b), A = l × b. Triangle: A = ½ × base × height. Circle: C = 2πr (or πd), A = πr². For irregular shapes, split them into rectangles and triangles.",
    concepts:[
      {t:"green", title:"📏 Units", body:"1 m = 100 cm, so 1 m² = 10 000 cm². Convert before calculating — 50 cm = 0.5 m."},
      {t:"teal", title:"🧮 How many items?", body:"Number of tiles = area to cover ÷ area of one tile. Round <strong>up</strong> and add a wastage allowance."},
      {t:"gold", title:"🎨 Paint", body:"Litres = area × coats ÷ coverage per litre. A 4 m × 2.7 m wall with 2 coats at 8 m²/L needs 2.7 L."},
    ],
    examples:[
      {title:"Fencing the garden", body:"Garden 12 m × 8 m.", answer:"P = 2(12 + 8) = <strong>40 m</strong> of fencing."},
      {title:"Tiles", body:"Area 96 m²; tile 0.5 m × 0.5 m; 10% extra.", answer:"96 ÷ 0.25 = 384 → × 1.1 = 422.4 → <strong>423 tiles</strong>."},
      {title:"Paint", body:"Wall 4 m × 2.7 m, 2 coats, 8 m² per litre.", answer:"10.8 × 2 ÷ 8 = <strong>2.7 L</strong> → buy 3 L."},
    ],
    formula:"Rectangle: P = 2(l + b), A = lb · Circle: C = 2πr, A = πr² · Triangle: A = ½bh",
    mistakes:["Mixing cm and m in one calculation.","Rounding down the number of tiles or tins (you'd run short).","Confusing perimeter (distance) with area (space)."],
    callout:{title:"Where you'll use this", body:"Building and renovating, farming (fencing camps), interior design, landscaping and quoting for small contracting jobs."},
    activity:"A circular garden bed has a diameter of 3 m. How much edging is needed, and what is its area?",
    activityAnswer:"C = π × 3 ≈ 9.42 m of edging. A = π × 1.5² ≈ 7.07 m².",
    examTip:"Write the formula from the formula sheet, substitute with units, and round only at the end — and round up for materials.",
    keyterms:[{w:"Perimeter",d:"Total distance around a shape"},{w:"Area",d:"Amount of surface inside a shape"},{w:"Wastage allowance",d:"Extra material bought for cutting and breakage"}],
    quiz:[
      {q:"Perimeter of a 5 m × 3 m rectangle:",opts:["8 m","15 m","16 m","30 m"],a:2,et:"2(5 + 3) = 16 m."},
      {q:"Area of a 6 m × 4 m room:",opts:["10 m²","20 m²","24 m²","48 m²"],a:2,et:"6 × 4 = 24 m²."},
      {q:"You calculate 41.2 tins of paint. You buy:",opts:["41","41.2","42","40"],a:2,et:"Always round up when buying materials."},
    ],
    conclusion:"Perimeter goes around, area fills inside. Measure carefully, convert units, and round up for materials."},

  1: {emoji:"🛢️", subtitle:"Grade 10–12 · How much a container holds",
    illusText:"How many litres of rainwater can your roof collect? Volume answers it — useful in a water-scarce country.",
    hook:{title:"Harvesting rain from the roof", body:"A 60 m² roof catches rain. In a 20 mm downpour, it collects 60 × 0.02 = 1.2 m³ = <strong>1 200 litres</strong>. A 2 500 L JoJo tank fills in about two good storms. Families and schools across South Africa use exactly this calculation to plan water storage."},
    intro:"<strong>Volume</strong> is the space inside a 3D object (m³, cm³). <strong>Capacity</strong> is how much liquid it holds (litres, ml). Key links: <strong>1 cm³ = 1 ml</strong>, <strong>1 000 cm³ = 1 L</strong>, <strong>1 m³ = 1 000 L</strong>. Rectangular prism: V = l × b × h. Cylinder: V = πr²h. <strong>Surface area</strong> is the total area of all outer faces (useful for wrapping, painting and making boxes).",
    concepts:[
      {t:"green", title:"📦 Rectangular containers", body:"A 2 m × 1 m × 0.5 m trough: V = 1 m³ = 1 000 L."},
      {t:"teal", title:"🛢️ Cylinders", body:"Tank with radius 0.8 m and height 1.6 m: V = π × 0.8² × 1.6 ≈ 3.22 m³ ≈ 3 217 L."},
      {t:"gold", title:"🎁 Surface area", body:"Box: SA = 2(lb + lh + bh). Cylinder: SA = 2πr² + 2πrh (top, bottom and the curved side)."},
    ],
    examples:[
      {title:"Rainwater", body:"60 m² roof, 20 mm of rain.", answer:"60 × 0.02 = 1.2 m³ = <strong>1 200 L</strong>."},
      {title:"Cylindrical tank", body:"r = 0.8 m, h = 1.6 m.", answer:"π × 0.64 × 1.6 ≈ <strong>3.22 m³ ≈ 3 217 L</strong>."},
      {title:"Lunch box", body:"20 cm × 15 cm × 6 cm. Capacity in litres?", answer:"1 800 cm³ = <strong>1.8 L</strong>."},
    ],
    formula:"Prism: V = lbh · Cylinder: V = πr²h · 1 m³ = 1 000 L · 1 000 cm³ = 1 L",
    mistakes:["Using diameter instead of radius in πr²h.","Forgetting to convert mm of rain to metres (20 mm = 0.02 m).","Mixing up volume (3D) and surface area (2D)."],
    callout:{title:"Where you'll use this", body:"Plumbing and water storage, farming (dams and troughs), packaging design, building (concrete volumes) and cooking."},
    activity:"A rectangular fish pond is 3 m long, 2 m wide and 0.6 m deep. How many litres of water does it hold?",
    activityAnswer:"3 × 2 × 0.6 = 3.6 m³ = 3 600 L.",
    examTip:"Write the conversion you're using (e.g. “1 m³ = 1 000 L”) — it earns a mark and prevents errors.",
    keyterms:[{w:"Volume",d:"Space occupied by a 3D object"},{w:"Capacity",d:"Amount of liquid a container can hold"},{w:"Surface area",d:"Total area of all outer faces"}],
    quiz:[
      {q:"1 m³ equals:",opts:["100 L","1 000 L","10 L","1 L"],a:1,et:"1 m³ = 1 000 litres."},
      {q:"Volume of a 2 m × 2 m × 2 m tank:",opts:["6 m³","8 m³","12 m³","24 m³"],a:1,et:"2 × 2 × 2 = 8 m³."},
      {q:"500 cm³ of water is:",opts:["0.5 L","5 L","50 L","500 L"],a:0,et:"1 000 cm³ = 1 L, so 500 cm³ = 0.5 L."},
    ],
    conclusion:"Volume tells you how much fits inside. Master the conversions and you can plan water, concrete and packaging."},

  2: {emoji:"⏰", subtitle:"Grade 10–12 · Timetables, durations and planning",
    illusText:"Missing the 05:45 taxi can make you late for an exam. Reading time and timetables is a life skill.",
    hook:{title:"Will you make it to the exam?", body:"Lindiwe's taxi leaves Soshanguve at <strong>05:45</strong> and the trip takes about 1 h 25 min, arriving at <strong>07:10</strong>. Her exam starts at 08:00. If there's a 30-minute delay, she'll still arrive at 07:40. Working with times, durations and timetables helps you plan — and avoid panic."},
    intro:"Time can be written in <strong>12-hour</strong> (with a.m./p.m.) or <strong>24-hour</strong> format (00:00–23:59). 1 hour = 60 minutes, 1 minute = 60 seconds, so time isn't decimal: 1.5 hours = 1 h 30 min. <strong>Elapsed time</strong> = end time − start time. Calendars help with dates, due dates and counting days.",
    concepts:[
      {t:"green", title:"🕐 Converting formats", body:"3:15 p.m. = 15:15. 00:30 = 12:30 a.m. 12:00 = noon."},
      {t:"teal", title:"⏱️ Elapsed time", body:"Count up in steps: 05:45 → 06:00 (15 min) → 07:00 (1 h) → 07:10 (10 min) = 1 h 25 min."},
      {t:"gold", title:"🍗 Rates of time", body:"Roast chicken: 20 min per 500 g plus 20 min. A 2 kg chicken: 4 × 20 + 20 = 100 min = 1 h 40 min."},
    ],
    examples:[
      {title:"The taxi", body:"Leaves 05:45, arrives 07:10.", answer:"Elapsed = <strong>1 h 25 min</strong>."},
      {title:"Decimal hours", body:"A job takes 2.75 h. In hours and minutes?", answer:"0.75 × 60 = 45 → <strong>2 h 45 min</strong>."},
      {title:"Cooking", body:"When must a 2 kg chicken go in to be ready at 18:30?", answer:"100 min before → <strong>16:50</strong>."},
    ],
    mistakes:["Treating 1.5 h as 1 h 50 min (it's 1 h 30 min).","Subtracting times as decimal numbers (e.g. 7.10 − 5.45).","Forgetting that 12:00 noon is 12 p.m."],
    callout:{title:"Where you'll use this", body:"Transport timetables, shift work and overtime pay, medication schedules, cooking and project planning."},
    activity:"A shift runs from 22:00 to 06:30. How long is it? If the rate is R45 per hour, what's the pay?",
    activityAnswer:"8 h 30 min = 8.5 h → 8.5 × 45 = R382.50.",
    examTip:"Show your “counting up” steps for elapsed time — it avoids errors and earns method marks.",
    keyterms:[{w:"24-hour time",d:"Time written from 00:00 to 23:59"},{w:"Elapsed time",d:"Time passed between two moments"},{w:"Timetable",d:"Table of scheduled times"}],
    quiz:[
      {q:"7:45 p.m. in 24-hour time:",opts:["07:45","17:45","19:45","21:45"],a:2,et:"Add 12 to p.m. hours: 7 + 12 = 19."},
      {q:"1.25 hours =",opts:["1 h 25 min","1 h 15 min","1 h 2.5 min","75 h"],a:1,et:"0.25 × 60 = 15 min."},
      {q:"From 09:50 to 11:20 is:",opts:["1 h 30 min","1 h 70 min","2 h 30 min","1 h 20 min"],a:0,et:"09:50 → 10:50 (1 h) → 11:20 (30 min)."},
    ],
    conclusion:"Time runs in 60s, not 10s. Count up carefully and you'll never miss the taxi — or the deadline."},

  3: {emoji:"🗺️", subtitle:"Grade 10–12 · Reading maps and plans",
    illusText:"4 cm on a map can be 2 km on the ground. The scale tells you exactly how far.",
    hook:{title:"How far is the walk to school?", body:"On a 1 : 50 000 map, the route from home to school measures 4 cm. Every 1 cm on the map is 50 000 cm (500 m) on the ground, so the walk is <strong>2 km</strong>. Builders use the same idea on house plans at 1 : 100, where 5.2 cm on paper is a <strong>5.2 m</strong> wall."},
    intro:"A <strong>scale</strong> shows how map or plan distances relate to real distances. A <strong>number scale</strong> like 1 : 50 000 means 1 unit on the map = 50 000 of the same units in reality. A <strong>bar scale</strong> is a ruler drawn on the map — it stays correct even if the map is enlarged or shrunk. Real distance = map distance × scale factor (then convert units).",
    concepts:[
      {t:"green", title:"📐 Number scale", body:"1 : 50 000 → 4 cm × 50 000 = 200 000 cm = 2 000 m = 2 km."},
      {t:"teal", title:"📏 Bar scale", body:"Measure the map distance, then compare with the bar. Useful when a map is printed at a different size."},
      {t:"gold", title:"🏠 Floor plans", body:"1 : 100 → 1 cm on paper = 100 cm = 1 m. Plans show walls, doors (arcs) and windows (thin lines)."},
    ],
    examples:[
      {title:"Walk to school", body:"4 cm on a 1 : 50 000 map.", answer:"4 × 50 000 = 200 000 cm = <strong>2 km</strong>."},
      {title:"House plan", body:"A wall is 5.2 cm on a 1 : 100 plan.", answer:"5.2 × 100 = 520 cm = <strong>5.2 m</strong>."},
      {title:"Map distance", body:"Two towns are 15 km apart. How far apart on a 1 : 250 000 map?", answer:"1 500 000 cm ÷ 250 000 = <strong>6 cm</strong>."},
    ],
    formula:"Real distance = map distance × scale factor",
    mistakes:["Forgetting to convert cm to m or km.","Using a number scale after the map has been resized (use the bar scale).","Measuring straight-line distance when the question asks for the road route."],
    callout:{title:"Where you'll use this", body:"Navigation and hiking, delivery and taxi routes, architecture and building, town planning and surveying."},
    activity:"On a 1 : 20 000 street map, a route measures 7.5 cm. How long is it in km? How long would it take to walk at 5 km/h?",
    activityAnswer:"7.5 × 20 000 = 150 000 cm = 1.5 km. Time = 1.5 ÷ 5 = 0.3 h = 18 min.",
    examTip:"Write the conversion chain: cm → m (÷ 100) → km (÷ 1 000). It's where most marks are lost.",
    keyterms:[{w:"Scale",d:"Ratio of map distance to real distance"},{w:"Bar scale",d:"Line marked with real distances"},{w:"Floor plan",d:"Scaled top-view drawing of a building"}],
    quiz:[
      {q:"On a 1 : 100 plan, 3 cm represents:",opts:["3 cm","30 cm","3 m","300 m"],a:2,et:"3 × 100 = 300 cm = 3 m."},
      {q:"1 : 50 000 means 1 cm represents:",opts:["50 m","500 m","5 km","50 km"],a:1,et:"50 000 cm = 500 m."},
      {q:"Which scale still works if a map is enlarged?",opts:["Number scale","Bar scale","Both","Neither"],a:1,et:"The bar scale grows with the map."},
    ],
    conclusion:"Scale links paper to the real world. Multiply, convert units, and check the answer is realistic."},

  4: {emoji:"🌡️", subtitle:"Grade 10–12 · Weather, cooking and converting temperatures",
    illusText:"Sutherland can drop below −10 °C in winter while Upington tops 40 °C in summer. Temperature data tells the story.",
    hook:{title:"Reading the weather forecast", body:"The forecast for Bloemfontein says <strong>min −2 °C, max 18 °C</strong> — a range of 20 °C in one day, so you'll need a jacket in the morning and a T-shirt by lunch. An American recipe says bake at 350 °F — that's about 177 °C. Converting and comparing temperatures is everyday Maths Lit."},
    intro:"Temperature is measured in degrees <strong>Celsius (°C)</strong> in South Africa. Some products and recipes use <strong>Fahrenheit (°F)</strong>. Conversions: <strong>°F = 1.8 × °C + 32</strong> and <strong>°C = (°F − 32) ÷ 1.8</strong>. Water freezes at 0 °C (32 °F) and boils at 100 °C (212 °F) at sea level. The <strong>range</strong> of temperatures = maximum − minimum.",
    concepts:[
      {t:"green", title:"🔁 Conversions", body:"25 °C × 1.8 + 32 = 77 °F. Oven 180 °C = 356 °F. Body temperature 98.6 °F = 37 °C."},
      {t:"teal", title:"➖ Negative temperatures", body:"From −2 °C to 18 °C is a change of 20 °C (18 − (−2))."},
      {t:"gold", title:"📊 Temperature graphs", body:"Climate graphs show average monthly temperatures — use them to compare places and seasons."},
    ],
    examples:[
      {title:"Daily range", body:"Min −2 °C, max 18 °C.", answer:"18 − (−2) = <strong>20 °C</strong>."},
      {title:"To Fahrenheit", body:"25 °C.", answer:"1.8 × 25 + 32 = <strong>77 °F</strong>."},
      {title:"To Celsius", body:"A recipe says 350 °F.", answer:"(350 − 32) ÷ 1.8 ≈ <strong>177 °C</strong>."},
    ],
    formula:"°F = 1.8 × °C + 32 · °C = (°F − 32) ÷ 1.8",
    mistakes:["Subtracting 32 after multiplying when going °F → °C (subtract first).","Getting the range wrong with negatives (18 − (−2) = 20, not 16).","Mixing up minimum and maximum."],
    callout:{title:"Where you'll use this", body:"Cooking and baking, agriculture (frost warnings), health (fever), weather reporting and cold-chain logistics for vaccines."},
    activity:"A thermometer shows a child's temperature as 101 °F. Convert it to °C. Is it a fever (above 38 °C)?",
    activityAnswer:"(101 − 32) ÷ 1.8 ≈ 38.3 °C — yes, a mild fever.",
    examTip:"Use brackets on your calculator for (°F − 32) ÷ 1.8 — the order of operations matters.",
    keyterms:[{w:"Celsius",d:"Temperature scale: water freezes at 0, boils at 100"},{w:"Fahrenheit",d:"Scale where water freezes at 32 and boils at 212"},{w:"Range",d:"Maximum minus minimum"}],
    quiz:[
      {q:"0 °C in Fahrenheit:",opts:["0 °F","32 °F","100 °F","−32 °F"],a:1,et:"1.8 × 0 + 32 = 32 °F."},
      {q:"Min −5 °C, max 10 °C. Range:",opts:["5 °C","10 °C","15 °C","−15 °C"],a:2,et:"10 − (−5) = 15 °C."},
      {q:"212 °F is:",opts:["Freezing","Body temperature","Boiling point of water","Room temperature"],a:2,et:"(212 − 32) ÷ 1.8 = 100 °C."},
    ],
    conclusion:"Celsius at home, Fahrenheit sometimes abroad. Convert carefully and watch your negatives."},

  5: {emoji:"⚖️", subtitle:"Grade 10–12 · Weighing, converting and comparing prices",
    illusText:"Is the 10 kg bag of mealie meal really cheaper than two 5 kg bags? Price per kilogram tells you.",
    hook:{title:"Big bag or small bag?", body:"A 10 kg bag of maize meal costs R89.99 and a 5 kg bag costs R49.99. Per kilogram, that's <strong>R9.00/kg</strong> versus <strong>R10.00/kg</strong>. Buying the big bag saves about R10 every 10 kg — over a year that's real money for a family. Unit prices turn shopping into a smart decision."},
    intro:"<strong>Mass</strong> is measured in grams (g), kilograms (kg) and tonnes (t): <strong>1 kg = 1 000 g</strong>, <strong>1 t = 1 000 kg</strong>. Small amounts use milligrams: 1 g = 1 000 mg. (In everyday language people say “weight”, but scientifically weight is a force.) <strong>Unit price</strong> = price ÷ quantity — the fairest way to compare products of different sizes.",
    concepts:[
      {t:"green", title:"🔢 Conversions", body:"2.5 kg = 2 500 g. 750 g = 0.75 kg. 3 t = 3 000 kg."},
      {t:"teal", title:"🛒 Unit price", body:"R89.99 ÷ 10 kg ≈ R9.00/kg. Shelf labels in many shops show this — check it!"},
      {t:"gold", title:"💊 Dosages", body:"Some medicines are dosed by body mass (mg per kg). Always follow the label or pharmacist — never guess a dose."},
    ],
    examples:[
      {title:"Maize meal", body:"10 kg for R89.99 vs 5 kg for R49.99.", answer:"<strong>R9.00/kg vs R10.00/kg</strong> → the 10 kg bag is cheaper per kg."},
      {title:"Luggage", body:"A suitcase limit is 23 kg. You pack 18.5 kg plus 5 items of 950 g each.", answer:"5 × 0.95 = 4.75 kg → 23.25 kg — <strong>0.25 kg over</strong>."},
      {title:"Recipe", body:"A recipe needs 0.75 kg flour. How many grams?", answer:"<strong>750 g</strong>."},
    ],
    formula:"1 kg = 1 000 g · 1 t = 1 000 kg · unit price = price ÷ quantity",
    mistakes:["Comparing total prices instead of unit prices.","Converting 0.75 kg as 75 g.","Ignoring that the bigger pack is only cheaper if you'll actually use it before it goes off."],
    callout:{title:"Where you'll use this", body:"Grocery shopping, running a spaza or food business, farming (crop yields per hectare), shipping costs and nursing."},
    activity:"Rice: 2 kg for R42.99 or 5 kg for R99.99. Which is cheaper per kg?",
    activityAnswer:"2 kg: R21.50/kg. 5 kg: R20.00/kg. The 5 kg pack is cheaper per kg.",
    examTip:"When comparing prices, calculate both unit prices with the same unit (both per kg or both per 100 g) and state which is better.",
    keyterms:[{w:"Mass",d:"Amount of matter, in g, kg or t"},{w:"Unit price",d:"Price per kg, per litre or per item"},{w:"Tonne",d:"1 000 kg"}],
    quiz:[
      {q:"1.2 kg in grams:",opts:["12 g","120 g","1 200 g","12 000 g"],a:2,et:"1.2 × 1 000 = 1 200 g."},
      {q:"R30 for 2 kg is a unit price of:",opts:["R15/kg","R60/kg","R32/kg","R28/kg"],a:0,et:"30 ÷ 2 = R15/kg."},
      {q:"1 tonne equals:",opts:["100 kg","1 000 kg","10 000 g","100 g"],a:1,et:"1 t = 1 000 kg."},
    ],
    conclusion:"Convert carefully and always compare unit prices. Small savings per kilogram add up fast."},
};

// ─── Module 2: Data & Probability ───────────────────────────────────────────
LESSON_DB.math_lit.m2 = {
  0: {emoji:"📋", subtitle:"Grade 10–12 · Asking the right questions",
    illusText:"Stats SA's census counts every person in the country. Your class survey works on the same principles — on a smaller scale.",
    hook:{title:"Should the tuck shop sell more fruit?", body:"The RCL wants to know if learners would buy fruit at the tuck shop. If they only ask their friends in the netball team, the results will be <strong>biased</strong>. A fair <strong>sample</strong> from every grade gives a much more reliable answer. Stats SA's census uses the same ideas to plan schools, clinics and roads for the whole country."},
    intro:"<strong>Data</strong> is information collected to answer a question. <strong>Population</strong>: the whole group you're interested in. <strong>Sample</strong>: the part you actually ask. A good sample is <strong>representative</strong> and <strong>random</strong>. Data can be <strong>categorical</strong> (e.g. favourite sport) or <strong>numerical</strong> — <strong>discrete</strong> (counted, e.g. number of siblings) or <strong>continuous</strong> (measured, e.g. height). Tools: questionnaires, interviews, observation and tally tables.",
    concepts:[
      {t:"green", title:"❓ Good questions", body:"Clear, neutral and easy to answer. Bad: “Don't you agree the tuck shop is too expensive?” (leading). Better: “How would you rate tuck shop prices? Cheap / Fair / Expensive.”"},
      {t:"teal", title:"⚖️ Bias", body:"Bias happens when a sample isn't representative: only asking one grade, one gender or only people online."},
      {t:"gold", title:"✏️ Tally tables", body:"Record responses with tallies (IIII with a line through for 5), then count frequencies."},
    ],
    examples:[
      {title:"Data type", body:"Number of taxis passing in 10 minutes.", answer:"<strong>Numerical, discrete</strong> (counted)."},
      {title:"Data type", body:"Learners' heights.", answer:"<strong>Numerical, continuous</strong> (measured)."},
      {title:"Biased?", body:"A survey about public transport is done only at a shopping mall parking lot.", answer:"<strong>Yes</strong> — mostly car owners, not taxi or bus users."},
    ],
    mistakes:["Asking leading questions.","Choosing a sample that's convenient instead of representative.","Mixing up discrete and continuous data."],
    callout:{title:"Where you'll use this", body:"Market research, public health surveys, Stats SA, community projects, journalism and any job that makes decisions with data."},
    activity:"Design three neutral questions for a survey about how learners get to school.",
    activityAnswer:"Example: 1) How do you usually travel to school? (Walk / Taxi / Bus / Car / Other) 2) How long does it take? (minutes) 3) How much do you spend per day on transport? (R)",
    examTip:"When asked to “comment on the sample”, discuss its size and whether it represents the whole population.",
    keyterms:[{w:"Sample",d:"Part of a population used to collect data"},{w:"Bias",d:"A distortion that makes results unrepresentative"},{w:"Discrete data",d:"Data that can be counted in whole numbers"}],
    quiz:[
      {q:"Favourite colour is:",opts:["Discrete","Continuous","Categorical","Ordinal only"],a:2,et:"It's a category, not a number."},
      {q:"A sample should be:",opts:["Your friends","Representative","As small as possible","Only teachers"],a:1,et:"It should fairly represent the population."},
      {q:"Mass of babies at birth is:",opts:["Discrete","Continuous","Categorical","Biased"],a:1,et:"Mass is measured, so it's continuous."},
    ],
    conclusion:"Good decisions need good data. Ask neutral questions to a fair sample, and record carefully."},

  1: {emoji:"📊", subtitle:"Grade 10–12 · Showing data clearly",
    illusText:"A good chart tells the story in five seconds. A bad one hides it — or misleads you.",
    hook:{title:"What sport does our class love?", body:"In a class of 40, 20 learners pick soccer, 10 netball, 6 rugby and 4 cricket. A <strong>pie chart</strong> shows that half the class loves soccer at a glance: soccer gets 180° of the circle. A <strong>bar chart</strong> makes it easy to compare the sports. Choosing the right chart is part of telling the truth with data."},
    intro:"<strong>Bar graphs</strong> compare categories (bars don't touch). <strong>Histograms</strong> show grouped numerical data (bars touch). <strong>Pie charts</strong> show parts of a whole: each sector angle = (frequency ÷ total) × 360°. <strong>Line graphs</strong> show change over time. Every graph needs a title, labelled axes with units, and a key if colours are used.",
    concepts:[
      {t:"green", title:"🥧 Pie chart angles", body:"Soccer: 20/40 × 360° = 180°. Netball 90°, rugby 54°, cricket 36°. Angles must add to 360°."},
      {t:"teal", title:"📊 Bar vs histogram", body:"Bar graph: categories (sports, provinces). Histogram: intervals of numbers (marks 0–9, 10–19 …)."},
      {t:"gold", title:"🔍 Misleading graphs", body:"Watch for axes that don't start at zero, uneven scales, 3D effects and missing labels."},
    ],
    examples:[
      {title:"Pie chart angle", body:"Netball: 10 out of 40 learners.", answer:"10/40 × 360° = <strong>90°</strong>."},
      {title:"Percentage", body:"What % chose rugby?", answer:"6/40 × 100 = <strong>15%</strong>."},
      {title:"Choose the chart", body:"Monthly electricity use over a year.", answer:"A <strong>line graph</strong> (change over time)."},
    ],
    formula:"Sector angle = (frequency ÷ total) × 360°",
    mistakes:["Pie chart angles that don't add up to 360°.","Leaving gaps between histogram bars (or none between bar-graph bars).","Missing titles, axis labels or units."],
    callout:{title:"Where you'll use this", body:"Business reports and presentations, news and journalism, school and municipal reports, and social media analytics."},
    activity:"Draw a pie chart of a household budget: rent R3 500, food R2 800, transport R1 000, other R1 700.",
    activityAnswer:"Total R9 000. Angles: rent 140°, food 112°, transport 40°, other 68° (sum 360°).",
    examTip:"Use a protractor for pie charts and show your angle calculations in a table — accuracy and working both earn marks.",
    keyterms:[{w:"Pie chart",d:"Circle divided into sectors showing parts of a whole"},{w:"Histogram",d:"Bar chart for grouped numerical data with touching bars"},{w:"Key/legend",d:"Explains colours or symbols on a graph"}],
    quiz:[
      {q:"In a pie chart, 25% of the data is a sector of:",opts:["25°","45°","90°","180°"],a:2,et:"0.25 × 360° = 90°."},
      {q:"Best for change over time:",opts:["Pie chart","Line graph","Tally table","Pictogram"],a:1,et:"Line graphs show trends over time."},
      {q:"In a histogram the bars:",opts:["Have gaps","Touch","Are circles","Are random widths"],a:1,et:"Numerical intervals are continuous, so the bars touch."},
    ],
    conclusion:"Pick the chart that fits the data, label everything, and watch out for graphs designed to mislead."},

  2: {emoji:"🧮", subtitle:"Grade 10–12 · Finding a typical value",
    illusText:"“The average taxi fare” — but which average? Mean, median and mode can tell different stories.",
    hook:{title:"What's a typical matric mark?", body:"Seven learners score 45, 52, 58, 61, 61, 67 and 99. The <strong>mean</strong> is 63.3, the <strong>median</strong> (middle) is 61 and the <strong>mode</strong> (most common) is 61. The one very high mark of 99 pulls the mean up. Choosing the right average helps schools, businesses and journalists describe data honestly."},
    intro:"<strong>Mean</strong> = sum of values ÷ number of values. <strong>Median</strong> = middle value when the data is in order (average of the two middle values if there's an even number). <strong>Mode</strong> = most frequent value. <strong>Range</strong> = highest − lowest (a measure of spread). Outliers affect the mean much more than the median.",
    concepts:[
      {t:"green", title:"📏 Order first", body:"Always sort the data before finding the median."},
      {t:"teal", title:"⚖️ Which average?", body:"Mean: uses every value. Median: best when there are outliers (e.g. salaries, house prices). Mode: best for categories (most popular shoe size)."},
      {t:"gold", title:"📐 Range", body:"Shows spread. A small range means the data is consistent."},
    ],
    examples:[
      {title:"Mean", body:"45, 52, 58, 61, 61, 67, 99.", answer:"443 ÷ 7 ≈ <strong>63.3</strong>."},
      {title:"Median and mode", body:"Same data.", answer:"Median = <strong>61</strong> (4th value). Mode = <strong>61</strong>."},
      {title:"Range", body:"Same data.", answer:"99 − 45 = <strong>54</strong>."},
    ],
    formula:"Mean = Σx ÷ n · Range = max − min",
    mistakes:["Finding the median without sorting.","Forgetting to divide by the number of values for the mean.","Saying there's no mode when two values tie (there can be two modes)."],
    callout:{title:"Where you'll use this", body:"School results, sports statistics, business sales reports, Stats SA income reports and comparing prices."},
    activity:"Daily taxi fares paid in one week: R18, R18, R22, R18, R25. Find the mean, median, mode and range.",
    activityAnswer:"Mean = 101 ÷ 5 = R20.20. Median = R18. Mode = R18. Range = R7.",
    examTip:"When asked “which measure is most appropriate”, mention outliers or skewness in your reason.",
    keyterms:[{w:"Mean",d:"Sum of values divided by the number of values"},{w:"Median",d:"Middle value of ordered data"},{w:"Outlier",d:"Value far from the rest of the data"}],
    quiz:[
      {q:"Mean of 4, 6, 8:",opts:["4","6","8","18"],a:1,et:"18 ÷ 3 = 6."},
      {q:"Median of 3, 9, 1, 7, 5:",opts:["1","5","7","9"],a:1,et:"Sorted: 1, 3, 5, 7, 9 → middle = 5."},
      {q:"Best average for house prices with one mansion:",opts:["Mean","Median","Range","Total"],a:1,et:"The median isn't pulled by the outlier."},
    ],
    conclusion:"Mean, median, mode — three ways to find typical. Check for outliers before you choose."},

  3: {emoji:"📈", subtitle:"Grade 11–12 · Looking for relationships in data",
    illusText:"Do learners who study more score higher? A scatter plot shows the pattern — and its limits.",
    hook:{title:"Does studying more help?", body:"A teacher plots each learner's weekly study hours against their test mark. The points trend upwards: more study, higher marks — a <strong>positive correlation</strong>. But ice-cream sales and drownings also rise together in summer — not because one causes the other, but because both increase when it's hot. <strong>Correlation isn't causation.</strong>"},
    intro:"A <strong>scatter plot</strong> shows pairs of numerical data as points on a grid. It helps you see a <strong>relationship (correlation)</strong> between two variables. <strong>Positive</strong>: both increase together. <strong>Negative</strong>: one increases as the other decreases. <strong>No correlation</strong>: no clear pattern. A <strong>trend line</strong> (line of best fit) summarises the pattern and can be used to make predictions.",
    concepts:[
      {t:"green", title:"📈 Reading the pattern", body:"Points close to a line → strong correlation. Widely scattered points → weak correlation."},
      {t:"teal", title:"🔮 Predicting", body:"Use the trend line to estimate values inside the data range (interpolation). Predicting far outside the range (extrapolation) is risky."},
      {t:"gold", title:"⚠️ Causation", body:"A correlation doesn't prove that one variable causes the other. Look for a third factor."},
    ],
    examples:[
      {title:"Type of correlation", body:"Car age vs resale value.", answer:"<strong>Negative</strong> — older cars are worth less."},
      {title:"Type of correlation", body:"Shoe size vs maths mark.", answer:"<strong>No correlation</strong>."},
      {title:"Prediction", body:"The trend line passes through (6 h, 70%). Predict for 6 hours.", answer:"About <strong>70%</strong> — an estimate, not a guarantee."},
    ],
    mistakes:["Joining scatter points with lines.","Saying correlation proves cause.","Extrapolating far beyond the data."],
    callout:{title:"Where you'll use this", body:"Health research, economics, sports analytics, marketing and any job that looks for patterns in data."},
    activity:"Suggest a third factor that could explain why towns with more police stations have more crime.",
    activityAnswer:"Population size: bigger towns have both more police stations and more crime incidents.",
    examTip:"Describe a scatter plot with both direction (positive/negative) and strength (strong/weak).",
    keyterms:[{w:"Scatter plot",d:"Graph of pairs of numerical data"},{w:"Correlation",d:"Relationship between two variables"},{w:"Trend line",d:"Line of best fit through the points"}],
    quiz:[
      {q:"Temperature vs heater sales is likely:",opts:["Positive","Negative","No correlation","Causal"],a:1,et:"Colder weather → more heaters sold."},
      {q:"Points close to a straight line show:",opts:["Weak correlation","Strong correlation","No data","Causation"],a:1,et:"Tight clustering means a strong relationship."},
      {q:"Correlation proves causation:",opts:["Always","Never necessarily","Only if positive","Only if strong"],a:1,et:"A third factor may explain both."},
    ],
    conclusion:"Scatter plots reveal relationships. Describe the direction and strength — and be careful about cause."},

  4: {emoji:"🎲", subtitle:"Grade 10–12 · Measuring chance",
    illusText:"“70% chance of rain” — should you take an umbrella? Probability helps you decide.",
    hook:{title:"What does “70% chance of rain” mean?", body:"The SA Weather Service forecasts a 70% chance of rain in Durban tomorrow. It means that on days with conditions like these, it rains about 7 out of 10 times. It might still stay dry — but taking an umbrella is a smart bet. Probability is about making good decisions when you can't be certain."},
    intro:"<strong>Probability</strong> measures how likely an event is, from <strong>0</strong> (impossible) to <strong>1</strong> (certain), often written as a fraction, decimal or percentage. <strong>Theoretical probability</strong> = favourable outcomes ÷ total possible outcomes (for equally likely outcomes). <strong>Experimental (relative) frequency</strong> = number of times it happened ÷ number of trials. P(not A) = 1 − P(A). Use tables and tree diagrams for two events.",
    concepts:[
      {t:"green", title:"🎲 Dice and coins", body:"P(6 on a die) = 1/6. P(heads) = 1/2. Two coins: HH, HT, TH, TT → P(two heads) = 1/4."},
      {t:"teal", title:"🔁 Experiments", body:"Toss a coin 100 times: you might get 46 heads (0.46). The more trials, the closer the relative frequency gets to 0.5."},
      {t:"gold", title:"🎟️ Gambling and risk", body:"Lotto and betting are designed so that, on average, players lose money. Probability shows why."},
    ],
    examples:[
      {title:"Die", body:"P(even number) on a fair die.", answer:"3 even numbers (2, 4, 6) out of 6 → <strong>1/2</strong>."},
      {title:"Complement", body:"P(rain) = 0.7. P(no rain)?", answer:"1 − 0.7 = <strong>0.3</strong>."},
      {title:"Two coins", body:"P(at least one head).", answer:"HH, HT, TH → <strong>3/4</strong>."},
    ],
    formula:"P(event) = favourable ÷ total · P(not A) = 1 − P(A)",
    mistakes:["Giving a probability greater than 1.","Forgetting outcomes in two-event problems (HT and TH are different).","Thinking a coin is “due” to land heads after several tails."],
    callout:{title:"Where you'll use this", body:"Insurance and risk assessment, weather forecasting, games and sports strategy, quality control and understanding gambling."},
    activity:"A bag has 3 red, 5 blue and 2 green sweets. Find P(blue) and P(not red).",
    activityAnswer:"Total 10. P(blue) = 5/10 = 1/2. P(not red) = 1 − 3/10 = 7/10.",
    examTip:"Write probabilities as simplified fractions unless the question asks for a decimal or percentage.",
    keyterms:[{w:"Probability",d:"How likely an event is, from 0 to 1"},{w:"Outcome",d:"A possible result of an experiment"},{w:"Relative frequency",d:"Times an event happened ÷ total trials"}],
    quiz:[
      {q:"P(rolling a 7 on a normal die):",opts:["1/6","1/7","0","1"],a:2,et:"A 7 is impossible on a six-sided die."},
      {q:"P(heads) = 0.5. After 5 tails in a row, P(heads) on the next toss is:",opts:["Higher","Lower","0.5","1"],a:2,et:"Each toss is independent."},
      {q:"A probability of 1 means:",opts:["Impossible","Unlikely","Even chance","Certain"],a:3,et:"1 means it will definitely happen."},
    ],
    conclusion:"Probability puts a number on uncertainty. Use it to make smarter choices — and to see through gambling hype."},

  5: {emoji:"📉", subtitle:"Grade 10–12 · Interpreting graphs in the news and on bills",
    illusText:"The same numbers can look scary or harmless depending on how the graph is drawn. Learn to read past the design.",
    hook:{title:"The scary petrol graph", body:"A news site shows a graph where the petrol price line shoots up steeply. Look closer: the vertical axis starts at R22, not R0, so a small rise of 50c looks like a huge jump. Reading graphs critically — checking axes, scales and sources — protects you from being misled by adverts, politicians and social media."},
    intro:"To read any graph: (1) read the <strong>title</strong>; (2) check the <strong>axes</strong> — what's measured and in what units; (3) check the <strong>scale</strong> and where it starts; (4) read values carefully; (5) describe <strong>trends</strong> (increasing, decreasing, constant, peaks). Graphs on electricity and water bills, tariff tables and payslips often combine tables and graphs.",
    concepts:[
      {t:"green", title:"🔍 Check the axes", body:"An axis that doesn't start at zero exaggerates changes. Uneven scales distort trends."},
      {t:"teal", title:"📈 Describe trends", body:"Use words like steadily increasing, sharp drop, levels off, peak in December."},
      {t:"gold", title:"🧾 Bills and tariffs", body:"Municipal bills often show usage per month as a bar graph. Compare months to spot leaks or high use."},
    ],
    examples:[
      {title:"Misleading axis", body:"Petrol rose from R22.50 to R23.00, but the axis starts at R22.40.", answer:"The rise is only <strong>50c (about 2%)</strong>; the graph exaggerates it."},
      {title:"Water bill", body:"Usage: 12 kL, 13 kL, 25 kL in three months. What might explain the jump?", answer:"A possible <strong>leak</strong> (or more people at home) — investigate."},
      {title:"Describe", body:"A line rises slowly Jan–Jun, then sharply Jul–Aug.", answer:"<strong>Gradual increase, then a sharp rise</strong> in July–August (e.g. winter electricity use)."},
    ],
    mistakes:["Reading values without checking units (kL vs L, R vs c).","Ignoring where the axis starts.","Describing a trend with only one data point."],
    callout:{title:"Where you'll use this", body:"Understanding bills and payslips, financial news, health statistics, election results and spotting fake news."},
    activity:"Find a graph in a newspaper or online. Is it misleading in any way? Explain.",
    activityAnswer:"Answers vary — check the axis start, scale, missing labels, source and whether the chart type suits the data.",
    examTip:"When asked if a graph is misleading, give a specific reason (e.g. “the vertical axis starts at 22, which exaggerates the increase”).",
    keyterms:[{w:"Axis",d:"Reference line showing what is measured"},{w:"Trend",d:"General direction of change in data"},{w:"Misleading graph",d:"A graph designed or drawn so it distorts the data"}],
    quiz:[
      {q:"A graph whose y-axis starts at 90 instead of 0:",opts:["Is always wrong","Can exaggerate differences","Hides all data","Is a pie chart"],a:1,et:"Small changes look bigger."},
      {q:"First thing to read on a graph:",opts:["The title","The colour","The last point","The source code"],a:0,et:"The title tells you what the graph is about."},
      {q:"1 kL equals:",opts:["10 L","100 L","1 000 L","1 L"],a:2,et:"Water bills use kilolitres: 1 kL = 1 000 L."},
    ],
    conclusion:"Read the title, the axes and the scale before the line. That's how you see what a graph really says."},
};

